function Clock({lang,compact=false,session="2026"}:{lang:Lang;compact?:boolean;session?:string}){
  const timeRef=useRef<HTMLSpanElement>(null),dateRef=useRef<HTMLSpanElement>(null),greetingRef=useRef<HTMLSpanElement>(null);
  useEffect(()=>{const update=()=>{const now=new Date();const h=Number(new Intl.DateTimeFormat("en",{hour:"numeric",hour12:false,timeZone:"Asia/Dhaka"}).format(now));const time=new Intl.DateTimeFormat(lang==="bn"?"bn-BD":"en-US",{timeZone:"Asia/Dhaka",hour:"2-digit",minute:"2-digit",second:"2-digit",hour12:true}).format(now);const date=new Intl.DateTimeFormat(lang==="bn"?"bn-BD":"en-GB",{timeZone:"Asia/Dhaka",weekday:"long",day:"2-digit",month:"long",year:"numeric"}).format(now);let greet="Good morning",label="";if(h<6){greet="Good night";label="ভোর"}else if(h<12){greet="Good morning";label="সকাল"}else if(h<15){greet="Good afternoon";label="দুপুর"}else if(h<18){greet="Good afternoon";label="বিকাল"}else if(h<20){greet="Good evening";label="সন্ধ্যা"}else{greet="Good night";label="রাত"}if(timeRef.current)timeRef.current.textContent=(lang==="bn"?`${label} `:"")+time;if(dateRef.current)dateRef.current.textContent=date;if(greetingRef.current)greetingRef.current.textContent=lang==="bn"?(h<12?"শুভ সকাল":h<18?"শুভ অপরাহ্ণ":"শুভ সন্ধ্যা"):greet};update();const timer=setInterval(update,1000);return()=>clearInterval(timer)},[lang]);
  if(compact)return <div className="compact-clock"><Clock3 size={15}/><span ref={timeRef}/><span className="clock-date" ref={dateRef}/></div>;
  return <section className="hero-clock"><div><div className="eyebrow"><Sparkles size={15}/><span ref={greetingRef}/></div><h1><span ref={timeRef}/></h1><p><span ref={dateRef}/></p></div><div className="clock-meta"><span>{lang==="bn"?"শিক্ষাবর্ষ":"Academic session"}</span><strong>{lang==="bn"?bnDigits(session):session}</strong><small><CalendarDays size={14}/> {lang==="bn"?"পরবর্তী: স্বাধীনতা দিবস · ২৬ মার্চ":"Next: Independence Day · 26 Mar"}</small></div></section>
}

function Login({onDone}:{onDone:()=>void}){
  const [role,setRole]=useState<"admin"|"teacher"|"student">("admin"),[error,setError]=useState(""),[busy,setBusy]=useState(false),[setup,setSetup]=useState(false);
  const submit=async(e:React.FormEvent<HTMLFormElement>)=>{e.preventDefault();setBusy(true);setError("");const f=new FormData(e.currentTarget);const body=setup?{action:"setup",name:f.get("name"),email:f.get("identifier"),password:f.get("password"),setupToken:f.get("setupToken")||undefined}:{action:"login",role,identifier:f.get("identifier"),password:f.get("password"),dob:f.get("dob")};try{const r=await fetch("/api/auth",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(body)});const j=await r.json();if(!r.ok)throw new Error(j.error);onDone()}catch(x){setError(x instanceof Error?x.message:"Sign in failed")}finally{setBusy(false)}};
  return <main className="login-shell"><div className="login-brand"><div className="logo-mark"><GraduationCap/></div><b>EduPulse</b><span>AMS</span></div><section className="login-card"><div className="login-intro"><div className="secure-icon"><ShieldCheck/></div><p>ACADEMY MANAGEMENT SYSTEM</p><h1>{setup?"Create school administrator":"Welcome back"}</h1><span>{setup?"Set up a secure administrator account":"Sign in to Shantipur Government Primary School"}</span></div>{!setup&&<div className="role-switch">{(["admin","teacher","student"] as const).map(r=><button type="button" className={role===r?"active":""} onClick={()=>setRole(r)} key={r}>{r==="student"?"Parent / Student":r[0].toUpperCase()+r.slice(1)}</button>)}</div>}<form onSubmit={submit}>{setup&&<><label>Full name<input name="name" required placeholder="Head teacher's name"/></label><label>Setup token (if configured)<input name="setupToken" type="password" placeholder="Server SETUP_TOKEN"/></label></>}<label>{role==="student"&&!setup?"Admission number":"Email or mobile"}<input name="identifier" autoComplete="username" required placeholder={role==="student"?"e.g. 2026001":"you@school.edu.bd"}/></label>{role==="student"&&!setup&&<label>Date of birth<input name="dob" type="date" required/></label>}<label>{role==="student"&&!setup?"4–6 digit portal PIN":"Password"}<input name="password" type="password" minLength={role==="student"?4:8} required autoComplete="current-password" placeholder="••••••••"/></label>{error&&<div className="form-error"><AlertCircle size={17}/>{error}</div>}<button className="primary wide" disabled={busy}>{busy?<><RefreshCw className="spin" size={17}/>Signing in…</>:<><LockKeyhole size={17}/>{setup?"Create secure account":"Secure sign in"}</>}</button></form><button className="text-button" onClick={()=>{setSetup(!setup);setError("")}}>{setup?"Back to sign in":"First run? Create an admin account"}</button></section><aside className="demo-banner"><Sparkles size={18}/><div><b>Demo mode</b><p>Admin: admin@demo.ams / Demo@2026<br/>Teacher: teacher@demo.ams / Teacher@2026<br/>Student: AMS-2026-0001 · DOB 2015-01-01 · PIN 4821</p></div></aside><p className="login-foot"><ShieldCheck size={15}/> Passwords are hashed and never stored in plain text.</p></main>
}

function Sidebar({user,school,view,setView,open,setOpen,lang}:{user:User;school:School;view:string;setView:(v:string)=>void;open:boolean;setOpen:(v:boolean)=>void;lang:Lang}){
 const nav: {id:string;icon:typeof Users;children?:string[]}[]=user.role==="admin"?navAdmin:user.role==="teacher"?navTeacher:navStudent;const [expanded,setExpanded]=useState<string[]>(["exam","results"]);
 return <><aside className={`sidebar ${open?"open":""}`}><div className="side-brand"><div className="logo-mark"><GraduationCap/></div><div><b>EduPulse</b><span>ACADEMY</span></div><button className="mobile-close" onClick={()=>setOpen(false)}><X/></button></div><div className="school-chip"><div className="school-avatar">শা</div><div><strong>{lang==="bn"?school.nameBn:school.nameEn}</strong><span><span className="dot"/> {lang==="bn"?"সক্রিয় বিদ্যালয়":"Active school"}</span></div></div><nav><p>MAIN MENU</p>{nav.map(item=>{const I=item.icon;const isActive=view===item.id||item.children?.includes(view);return <div key={item.id}><button className={isActive?"active":""} onClick={()=>{if(item.children)setExpanded(s=>s.includes(item.id)?s.filter(x=>x!==item.id):[...s,item.id]);else{setView(item.id);setOpen(false)}}}><I size={19}/><span>{tr(item.id,lang)}</span>{item.children&&(expanded.includes(item.id)?<ChevronDown size={15}/>:<ChevronRight size={15}/>)}</button>{item.children&&expanded.includes(item.id)&&<div className="subnav">{item.children.map(c=><button className={view===c?"active":""} key={c} onClick={()=>{setView(c);setOpen(false)}}>{tr(c,lang)}</button>)}</div>}</div>})}</nav><div className="side-help"><div><BookOpen size={18}/></div><b>{lang==="bn"?"সাহায্য প্রয়োজন?":"Need help?"}</b><p>{lang==="bn"?"ব্যবহার নির্দেশিকা দেখুন":"Read the administrator guide"}</p><button>View guide</button></div><div className="side-user"><div className="avatar">{user.name.split(" ").map(x=>x[0]).slice(0,2).join("")}</div><div><b>{user.name}</b><span>{user.role}</span></div><MoreHorizontal size={18}/></div></aside>{open&&<div className="backdrop" onClick={()=>setOpen(false)}/>}</>
}

function Stat({icon:Icon,label,value,trend,tone}:{icon:typeof Users;label:string;value:string;trend:string;tone:string}){return <article className="stat-card"><div className={`stat-icon ${tone}`}><Icon/></div><div><span>{label}</span><strong>{value}</strong><small className={trend.startsWith("+")?"up":""}>{trend}</small></div><button><MoreHorizontal/></button></article>}
function BarChart({rows,lang}:{rows:Row[];lang:Lang}){const counts=[1,2,3,4,5].map(c=>rows.filter(r=>Number(r.data.class)===c).length),max=Math.max(...counts);return <div className="bar-chart">{counts.map((n,i)=><div className="bar-item" key={i}><span>{lang==="bn"?bnDigits(n):n}</span><div style={{height:`${Math.max(12,n/max*145)}px`}}/><small>{lang==="bn"?`শ্রেণি ${bnDigits(i+1)}`:`Class ${i+1}`}</small></div>)}</div>}
function Donut({rows}:{rows:Row[]}){const male=rows.filter(r=>r.data.gender==="Male").length,pct=Math.round(male/Math.max(1,rows.length)*100);return <div className="donut-wrap"><div className="donut" style={{background:`conic-gradient(#155eef 0 ${pct}%,#ef6b8a ${pct}% 100%)`}}><div><strong>{rows.length}</strong><span>Total</span></div></div><div className="legend"><span><i className="blue"/> Boys <b>{pct}%</b></span><span><i className="pink"/> Girls <b>{100-pct}%</b></span></div></div>}
function Dashboard({rows,lang,user,setView}:{rows:Row[];lang:Lang;user:User;setView:(v:string)=>void}){const students=rows.filter(r=>r.type==="student"),teachers=rows.filter(r=>r.type==="teacher"),payments=rows.filter(r=>r.type==="payment"),attendance=rows.filter(r=>r.type==="attendance"),notices=rows.filter(r=>r.type==="notice");const collected=payments.reduce((a,r)=>a+Number(r.data.amount||0)-Number(r.data.discount||0),0);const p=attendance.filter(r=>r.data.status==="Present").length/Math.max(1,attendance.length)*100;return <><Clock lang={lang} session="2026"/><div className="stats-grid"><Stat icon={Users} label={lang==="bn"?"মোট শিক্ষার্থী":"Total students"} value={lang==="bn"?bnDigits(students.length):String(students.length)} trend="+12 this session" tone="blue"/><Stat icon={UserCheck} label={lang==="bn"?"মোট শিক্ষক":"Total teachers"} value={lang==="bn"?bnDigits(teachers.length):String(teachers.length)} trend="All positions filled" tone="violet"/><Stat icon={ClipboardCheck} label={lang==="bn"?"উপস্থিতি হার":"Attendance today"} value={`${lang==="bn"?bnDigits(p.toFixed(1)):p.toFixed(1)}%`} trend="+2.4% vs last week" tone="green"/><Stat icon={CreditCard} label={lang==="bn"?"ফি আদায়":"Fees collected"} value={`৳${lang==="bn"?bnDigits(collected.toLocaleString()):collected.toLocaleString()}`} trend="+8.2% this month" tone="amber"/></div><div className="dashboard-grid"><article className="panel wide-panel"><PanelTitle title={lang==="bn"?"শ্রেণিভিত্তিক শিক্ষার্থী":"Students by class"} subtitle={lang==="bn"?"বর্তমান শিক্ষাবর্ষ":"Current academic session"}/><BarChart rows={students} lang={lang}/></article><article className="panel"><PanelTitle title={lang==="bn"?"লিঙ্গ অনুপাত":"Gender ratio"} subtitle="All enrolled students"/><Donut rows={students}/></article><article className="panel attendance-panel"><PanelTitle title={lang==="bn"?"দ্রুত উপস্থিতি":"Quick attendance"} subtitle="Mark today's class" action={<button onClick={()=>setView("attendance")}>{tr("viewAll",lang)}</button>}/><div className="class-pills">{[1,2,3,4,5].map(c=><button key={c} className={c===3?"active":""}>{lang==="bn"?`শ্রেণি ${bnDigits(c)}`:`Class ${c}`}</button>)}</div>{students.filter(s=>s.data.class==="3").slice(0,4).map((s,i)=><div className="quick-row" key={s.id}><div className="mini-avatar">{val(s.data.nameEn).slice(0,1)}</div><div><b>{lang==="bn"?val(s.data.nameBn):val(s.data.nameEn)}</b><span>Roll {val(s.data.roll)} · Section {val(s.data.section)}</span></div><div className="status-buttons"><button className={i!==2?"present":""}><Check/> P</button><button className={i===2?"absent":""}><X/> A</button></div></div>)}<button className="primary wide" onClick={()=>setView("attendance")}>Save attendance <ChevronRight size={17}/></button></article><article className="panel activity-panel"><PanelTitle title={lang==="bn"?"সাম্প্রতিক কার্যক্রম":"Recent activity"} subtitle="Latest school updates" action={<button>View log</button>}/>{[{i:CreditCard,t:"Payment received",d:"Receipt R-1086 · ৳350",c:"green"},{i:Users,t:"New student admitted",d:"Nusrat Jahan · Class 2A",c:"blue"},{i:Award,t:"Marks submitted",d:"Mathematics · Class 4",c:"violet"},{i:Bell,t:"Notice published",d:val(notices[0]?.data.title)||"Annual Sports Day",c:"amber"}].map((a,i)=><div className="activity-row" key={i}><div className={`activity-icon ${a.c}`}><a.i/></div><div><b>{a.t}</b><span>{a.d}</span></div><small>{i+1}h ago</small></div>)}</article></div></>}
function PanelTitle({title,subtitle,action}:{title:string;subtitle?:string;action?:React.ReactNode}){return <header className="panel-title"><div><h3>{title}</h3>{subtitle&&<p>{subtitle}</p>}</div>{action}</header>}

